  1	<script lang="ts">
  2		// AC: @web-dashboard ac-11
  3		import type { ItemSummary } from '@kynetic-ai/shared';
  4		import { Badge } from '$lib/components/ui/badge';
  5		import ChevronRight from '@lucide/svelte/icons/chevron-right';
  6		import { createEventDispatcher } from 'svelte';
  7	
  8		export let items: ItemSummary[];
  9	
 10		const dispatch = createEventDispatcher<{
 11			select: string;
 12		}>();
 13	
 14		// Track expanded nodes
 15		let expandedNodes = new Set<string>();
 16	
 17		// Build hierarchical tree structure
 18		interface TreeNode {
 19			item: ItemSummary;
 20			children: TreeNode[];
 21		}
 22	
 23		function buildTree(flatItems: ItemSummary[]): TreeNode[] {
 24			const nodeMap = new Map<string, TreeNode>();
 25			const roots: TreeNode[] = [];
 26	
 27			// Create nodes for all items
 28			flatItems.forEach((item) => {
 29				nodeMap.set(item._ulid, { item, children: [] });
 30			});
 31	
 32			// Build parent-child relationships
 33			flatItems.forEach((item) => {
 34				const node = nodeMap.get(item._ulid);
 35				if (!node) return;
 36	
 37				if (item.parent) {
 38					const parentNode = nodeMap.get(item.parent);
 39					if (parentNode) {
 40						parentNode.children.push(node);
 41					} else {
 42						roots.push(node);
 43					}
 44				} else {
 45					roots.push(node);
 46				}
 47			});
 48	
 49			return roots;
 50		}
 51	
 52		function toggleExpand(ulid: string) {
 53			if (expandedNodes.has(ulid)) {
 54				expandedNodes.delete(ulid);
 55			} else {
 56				expandedNodes.add(ulid);
 57			}
 58			// Trigger reactivity
 59			expandedNodes = expandedNodes;
 60		}
 61	
 62		function selectItem(item: ItemSummary) {
 63			dispatch('select', item._ulid);
 64		}
 65	
 66		function getTypeColor(type: string): string {
 67			const colors: Record<string, string> = {
 68				module: 'bg-purple-500',
 69				feature: 'bg-blue-500',
 70				requirement: 'bg-green-500',
 71				trait: 'bg-yellow-500'
 72			};
 73			return colors[type] || 'bg-gray-500';
 74		}
 75	
 76		$: tree = buildTree(items);
 77	</script>
 78	
 79	<!-- Recursive tree node snippet -->
 80	{#snippet renderNode(node: TreeNode, level: number)}
 81		{@const isExpanded = expandedNodes.has(node.item._ulid)}
 82		{@const hasChildren = node.children.length > 0}
 83		<div data-testid="tree-node tree-node-{node.item.type}">
 84			<div class="flex items-center gap-1 py-2 px-2 rounded-md hover:bg-muted/50">
 85				<!-- Expand/collapse button (only if has children) -->
 86				{#if hasChildren}
 87					<button
 88						type="button"
 89						class="p-1 rounded hover:bg-muted transition-transform"
 90						class:rotate-90={isExpanded}
 91						onclick={() => toggleExpand(node.item._ulid)}
 92						data-testid="expand-toggle"
 93						aria-expanded={isExpanded}
 94						aria-label={isExpanded ? 'Collapse' : 'Expand'}
 95					>
 96						<ChevronRight class="h-4 w-4" />
 97					</button>
 98				{:else}
 99					<!-- Placeholder for alignment -->
100					<div class="w-6"></div>
101				{/if}
102	
103				<!-- Item content (clickable for selection) -->
104				<button
105					type="button"
106					class="flex items-center gap-2 flex-1 text-left"
107					onclick={() => selectItem(node.item)}
108					data-testid="node-title"
109				>
110					<Badge class={getTypeColor(node.item.type)}>{node.item.type}</Badge>
111					<span class="font-medium">{node.item.title}</span>
112					{#if node.item.tags && node.item.tags.length > 0}
113						<div class="flex gap-1 ml-auto">
114							{#each node.item.tags.slice(0, 2) as tag}
115								<Badge variant="outline" class="text-xs">{tag}</Badge>
116							{/each}
117						</div>
118					{/if}
119				</button>
120			</div>
121	
122			<!-- Children (conditionally rendered) -->
123			{#if hasChildren && isExpanded}
124				<div class="pl-4 border-l-2 border-border ml-4" data-testid="tree-node-child">
125					{#each node.children as child (child.item._ulid)}
126						{@render renderNode(child, level + 1)}
127					{/each}
128				</div>
129			{/if}
130		</div>
131	{/snippet}
132	
133	<div class="space-y-1" data-testid="spec-tree-container">
134		{#if items.length === 0}
135			<p class="text-center text-muted-foreground py-8">No spec items found</p>
136		{:else}
137			<div class="space-y-1" data-testid="spec-tree">
138				{#each tree as node (node.item._ulid)}
139					{@render renderNode(node, 0)}
140				{/each}
141			</div>
142		{/if}
143	</div>

