 27			// Create nodes for all items
 28			flatItems.forEach((item) => {
 29				nodeMap.set(item._ulid, { item, children: [] });
 30			});
 31	
 32			// Build parent-child relationships
 33			flatItems.forEach((item) => {
 34				const node = nodeMap.get(item._ulid);
 35				if (!node) return;
 36	
 37				if (item.parent) {
 38					const parentNode = nodeMap.get(item.parent);
 39					if (parentNode) {
 40						parentNode.children.push(node);
 41					} else {
 42						roots.push(node);
 43					}
 44				} else {
 45					roots.push(node);
 46				}
 47			});
